window.__PLEDGE_SNAPSHOT = {"t":"2026-08-23T05:12:52.896Z","rows":[{"id":"p-20260816-zy5mbq","createdAt":"2026-08-16T14:41:27.430Z","publishedAt":"2026-08-16T15:47:22.873Z","name":"Alex","location":"North Canton","barrier":"Housing","why":"","photoId":""},{"id":"p-20260809-8olrxj","createdAt":"2026-08-09T16:16:42.643Z","publishedAt":"2026-08-10T17:18:29.257Z","name":"Ankita","location":"Kureel","barrier":"Debt & credit","why":"Minimum payment traps aren't accidental - they're designed so the debt barely shrinks while interest compounds. The markup on 'easy' EMIs is rarely disclosed clearly, and by the time you do the math, you're already paying double for something you could've afforded outright.","photoId":"1Ylqc-k048nwhd4Eb97J0SKGJZsolPTbu"},{"id":"p-20260807-dgyq52","createdAt":"2026-08-07T07:29:48.669Z","publishedAt":"2026-08-07T13:32:52.901Z","name":"Hilya","location":"Windhoek, Namibia","barrier":"Housing","why":"We have a crisis that we are failing to acknowledge. Housing is a basic necessity but the cost of housing is just too ridiculous for one to even fathom. It’s like as normal citizens we have to beg just to have affordable roofing over our heads when land is given to us for free by nature itself","photoId":"1jTv1rUl1u9kxyM3i9wZB8OHZzCWicJDB"},{"id":"p-20260806-51iwoy","createdAt":"2026-08-06T18:10:58.636Z","publishedAt":"2026-08-06T18:15:15.807Z","name":"Jose","location":"Panama City, Panama","barrier":"Education","why":"\"Although it has been a national law for two years now, financial education is not a governmental priority, and private sector efforts are just as scarce and relatively limited. The easiest way to find it is online, through social media, YouTube, and websites. But most content creators charge relatively large amounts of money, money that teens and young adults may not be able to afford.\"","photoId":""},{"id":"p-20260806-qyr44l","createdAt":"2026-08-06T17:54:39.746Z","publishedAt":"2026-08-06T17:59:40.114Z","name":"Devin","location":"New Jersey","barrier":"Education","why":"College should be a place to grow, not a financial gamble. Students deserve clear financial aid information so they can make informed decisions without hidden costs or confusing offers. As a student applying to college, I’ve experienced how confusing the process can be and how difficult it is to understand the true cost of attendin","photoId":"1W-E6O_U0KgJNS215_qheiTqJ-_JRudfX"},{"id":"p-20260805-3g7w5g","createdAt":"2026-08-05T18:40:27.440Z","publishedAt":"2026-08-05T20:45:42.736Z","name":"Taylor","location":"New York, NY (& Ohio!)","barrier":"Housing","why":"Working in personal finance has shown me how much housing affects every other financial goal. When rent and home prices grow faster than incomes, it becomes harder for people to build financial security and plan for their future.","photoId":""},{"id":"p-20260805-k5v9fi","createdAt":"2026-08-05T17:29:41.906Z","publishedAt":"2026-08-05T17:36:50.327Z","name":"Liz","location":"Mexico","barrier":"Housing","why":"Housing costs are a major concern for Mexican youth because it makes independence and access to a home increasingly difficult.","photoId":""},{"id":"p-20260805-te26nr","createdAt":"2026-08-05T16:27:52.482Z","publishedAt":"2026-08-05T17:27:29.129Z","name":"Soham Patel","location":"NYC","barrier":"Housing","why":"","photoId":"1SY_gxT5JWXhV7eaTIksBkLOPp39XlHlS"},{"id":"p-20260804-06r8ea","createdAt":"2026-08-04T15:18:05.564Z","publishedAt":"2026-08-05T17:27:26.512Z","name":"Kevin","location":"Cleveland","barrier":"Education","why":"Bob's class needs to be taught EVERYWHERE!","photoId":""},{"id":"p-20260804-h8fv3v","createdAt":"2026-08-04T20:19:57.854Z","publishedAt":"2026-08-05T17:27:23.248Z","name":"Samantha S.","location":"Charlotte, NC","barrier":"Food access","why":"Food insecurity is a big problem in my community. We need to figure out solutions and work together.","photoId":""},{"id":"p-20260805-gmb3px","createdAt":"2026-08-05T16:07:42.820Z","publishedAt":"2026-08-05T16:08:53.920Z","name":"Anthony","location":"Columbus, OH","barrier":"Debt & credit","why":"Predatory lenders intentionally target young people with tight budgets, trapping us in cycles of debt before we even get a financial foothold. I am standing against this barrier because your bank account shouldn't determine your vulnerability to financial traps.","photoId":"12FlldE8le4GiIbcw-7FVdRCTzABqATOn"},{"id":"p-20260803-h7wpsn","createdAt":"2026-08-03T19:58:50.456Z","publishedAt":"2026-08-03T19:59:04.164Z","name":"Ashley","location":"San Francisco, California","barrier":"Healthcare costs","why":"Health insurance is too expensive.","photoId":""},{"id":"p-20260803-79b2yg","createdAt":"2026-08-03T19:49:33.478Z","publishedAt":"2026-08-03T19:55:23.069Z","name":"Kevin","location":"Cincinnati OH","barrier":"Debt & credit","why":"30% APR is predatory","photoId":""},{"id":"p-20260731-9rud71","createdAt":"2026-07-31T05:56:08.657Z","publishedAt":"2026-07-31T19:58:54.998Z","name":"Anonymous","location":"north ridgeville ohio","barrier":"Work & income","why":"","photoId":""}]};
